// Divides fr_t `a` by `b`.
// NOTE: behavior for b == 0 is unspecified.
static void fr_div(fr_t *out, const fr_t *a, const fr_t *b) {
    fr_t tmp;
    blst_fr_eucl_inverse(&tmp, b);
    blst_fr_mul(out, a, &tmp);
}

